import subprocess

# Load reference db into memory
refs = {}
with open('/task/input/reference_db.fasta') as f:
    cur_id, cur_seq = None, []
    for line in f:
        line = line.strip()
        if line.startswith('>'):
            if cur_id: refs[cur_id] = ''.join(cur_seq)
            cur_id = line[1:].split()[0]
            cur_seq = []
        else:
            cur_seq.append(line)
    if cur_id: refs[cur_id] = ''.join(cur_seq)

ref_tax = {}
with open('/task/input/reference_taxonomy.tsv') as f:
    next(f)
    for line in f:
        r, g = line.strip().split('\t')
        ref_tax[r] = g

# Check the 45 non-chimera sequences
with open('/tmp/work/ref_nonchim.fa') as f:
    candidates = []
    cur_id, cur_s = None, []
    for line in f:
        line = line.strip()
        if line.startswith('>'):
            if cur_id: candidates.append((cur_id, ''.join(cur_s)))
            cur_id, cur_s = line, []
        else:
            cur_s.append(line)
    if cur_id: candidates.append((cur_id, ''.join(cur_s)))

# Search each candidate against reference_db.fasta (exact matches first)
exact_matches = {}
for r_id, r_seq in refs.items():
    exact_matches[r_seq] = r_id

for i, (cid, cseq) in enumerate(candidates):
    exact_hit = exact_matches.get(cseq, None)
    if exact_hit:
        print(f"{i:2d} EXACT match to {exact_hit} ({ref_tax[exact_hit]}), len={len(cseq)}")
    else:
        # Find best match
        print(f"{i:2d} NO EXACT MATCH, len={len(cseq)}")
